"""Real CPU model checks for contracts inferred from customer validation cases."""

from __future__ import annotations

import copy
import json
from pathlib import Path
import struct
import sys
import tempfile
import unittest
from unittest import mock

try:
    import torch
except ImportError:
    torch = None

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))
from model_builder.build import worker
from model_builder.build.inputs import resolve_inputs


ADAPTER = """import torch

class Projection(torch.nn.Module):
    def __init__(self, config):
        super().__init__()
        self.scale = torch.nn.Parameter(torch.tensor([99.0]))
        assert self.scale.device.type == 'cpu'
        self.config = config
        self.calls = 0

    def forward(self, coordinates, coefficients):
        assert not self.training
        if self.config.get('forbid_eager'):
            raise AssertionError('invalid input reached eager inference')
        self.calls += 1
        value = coordinates @ coefficients * self.scale
        mode = self.config.get('output')
        if mode == 'shape' and self.calls == 2:
            value = value.squeeze(-1)
        if mode == 'dtype':
            value = value.double()
        if mode == 'nonfinite':
            value = value * float('nan')
        if mode == 'scalar':
            value = value.sum()
        if mode == 'zero':
            value = value[:0]
        if mode == 'empty':
            return ()
        if mode == 'dict':
            return {'value': value}
        if mode == 'count' and self.calls == 2:
            return value
        return value, value.sum().reshape(1)


def create_model(config, assets):
    return Projection(config)


def create_cases(config, assets):
    coordinates = torch.tensor([[1., 2.], [3., 4.]])
    coefficients = torch.tensor([[1.], [2.]])
    mode = config.get('input')
    if mode == 'dtype':
        coordinates = coordinates.double()
    if mode == 'integer':
        coordinates = coordinates.long()
    if mode == 'scalar':
        coordinates = coordinates.sum()
    if mode == 'zero':
        coordinates = coordinates[:0]
    if mode == 'nonfinite':
        coordinates = coordinates * float('nan')
    if mode == 'nontensor':
        coordinates = [[1., 2.], [3., 4.]]
    first = (coordinates, coefficients)
    if mode == 'empty':
        return []
    if mode == 'empty-tuple':
        return [()]
    if mode == 'list':
        return [[coordinates, coefficients]]
    if mode == 'nontensor':
        return [first]
    if mode == 'count':
        return [first, (coordinates,)]
    if mode == 'shape':
        return [first, (coordinates[:1], coefficients)]
    return [first, (coordinates + 1., coefficients)]
"""


@unittest.skipIf(torch is None, "requires the producer Torch environment")
class AuthoringWorkerTests(unittest.TestCase):
    def setUp(self):
        temporary = tempfile.TemporaryDirectory()
        self.addCleanup(temporary.cleanup)
        self.root = Path(temporary.name).resolve()
        self.recipe_path = self.root / "recipe.json"
        self.config_path = self.root / "config.json"
        self.config_path.write_text("{}")
        self.checkpoint_path = self.root / "checkpoint.pt"
        torch.save({"scale": torch.tensor([3.0])}, self.checkpoint_path)
        (self.root / "export.py").write_text(ADAPTER)
        self.recipe = {
            "format_version": 2,
            "name": "customer-projection",
            "version": "0.1.0",
            "adapter": "export.py",
            "factory": "create_model",
            "cases": "create_cases",
            "config": {"path": "config.json"},
            "checkpoint": {"format": "torch-state-dict", "path": "checkpoint.pt"},
        }
        self.recipe_path.write_text(json.dumps(self.recipe))

    def prepare(self, **options):
        return worker._prepare_model(
            self.recipe,
            self.recipe_path,
            "cpu",
            model_inputs=resolve_inputs(self.recipe, self.recipe_path),
            infer_contract=True,
            **options,
        )

    def test_shape_free_adapter_infers_inputs_and_outputs_from_loaded_model(self):
        original = copy.deepcopy(self.recipe)
        try:
            prepared = self.prepare()
        except ValueError as error:
            self.fail(f"valid shape-free model preparation was rejected: {error}")
        self.assertEqual(
            prepared["tensor_contract"],
            {
                "inputs": [
                    {"name": "input_0", "dtype": "float32", "shape": [2, 2]},
                    {"name": "input_1", "dtype": "float32", "shape": [2, 1]},
                ],
                "outputs": [
                    {"name": "output_0", "dtype": "float32", "shape": [2, 1]},
                    {"name": "output_1", "dtype": "float32", "shape": [1]},
                ],
            },
        )
        self.assertEqual(len(prepared["cases"]), 2)
        self.assertEqual(
            struct.unpack("=2f", prepared["references"][0][0]["data"]), (15.0, 33.0)
        )
        self.assertEqual(
            struct.unpack("=2f", prepared["references"][1][0]["data"]), (24.0, 42.0)
        )
        self.assertEqual(self.recipe, original)

    def test_optional_names_propagate_to_records_and_contract(self):
        self.recipe.update(
            input_names=["coordinates", "coefficients"],
            output_names=["prediction", "total"],
        )
        prepared = self.prepare()
        for key in ("inputs", "outputs"):
            expected = self.recipe["input_names" if key == "inputs" else "output_names"]
            self.assertEqual(
                [item["name"] for item in prepared["tensor_contract"][key]], expected
            )
            records = prepared["inputs" if key == "inputs" else "references"]
            self.assertEqual([item["name"] for item in records[0]], expected)

    def test_checkpoint_is_loaded_once_with_cpu_weights_only(self):
        with mock.patch.object(torch, "load", wraps=torch.load) as load:
            prepared = self.prepare()
        self.assertEqual(load.call_count, 1)
        self.assertEqual(
            load.call_args.kwargs, {"weights_only": True, "map_location": "cpu"}
        )
        self.assertEqual(prepared["model"].scale.device.type, "cpu")

    def test_strict_checkpoint_validation_precedes_eager_contract_inference(self):
        self.config_path.write_text('{"forbid_eager":true}')
        for issue, state in (
            ("keys", {}),
            ("keys", {"scale": torch.tensor([3.0]), "extra": torch.tensor([1.0])}),
            ("shape", {"scale": torch.ones(2)}),
            ("dtype", {"scale": torch.ones(1, dtype=torch.float64)}),
            ("nonfinite", {"scale": torch.tensor([float("inf")])}),
            ("plain", {"state_dict": {"scale": torch.tensor([3.0])}}),
        ):
            with self.subTest(issue=issue):
                torch.save(state, self.checkpoint_path)
                with self.assertRaisesRegex(ValueError, issue):
                    self.prepare()

    def test_invalid_input_contracts_are_rejected_before_eager_execution(self):
        for mode, expected in (
            ("dtype", "dtype"),
            ("integer", "dtype"),
            ("scalar", "positive shape"),
            ("zero", "positive shape"),
            ("nontensor", "tensor"),
            ("empty", "at least one case"),
            ("empty-tuple", "non-empty|input count"),
            ("list", "tuples"),
        ):
            with self.subTest(mode=mode):
                self.config_path.write_text(
                    json.dumps({"input": mode, "forbid_eager": True})
                )
                with self.assertRaisesRegex(ValueError, expected):
                    self.prepare()

    def test_later_inputs_must_match_first_case_shape_and_count(self):
        for mode in ("shape", "count"):
            with self.subTest(mode=mode):
                self.config_path.write_text(json.dumps({"input": mode}))
                with self.assertRaisesRegex(ValueError, mode):
                    self.prepare()

    def test_outputs_must_be_static_nonempty_positive_fp32_tensors(self):
        for mode, expected in (
            ("shape", "shape"),
            ("count", "count"),
            ("dtype", "dtype"),
            ("scalar", "positive shape"),
            ("zero", "positive shape"),
            ("empty", "non-empty"),
            ("dict", "outputs.*tensor"),
        ):
            with self.subTest(mode=mode):
                self.config_path.write_text(json.dumps({"output": mode}))
                with self.assertRaisesRegex((ValueError, TypeError), expected):
                    self.prepare()

    def test_nonfinite_inputs_and_outputs_remain_rejected(self):
        for kind in ("input", "output"):
            with self.subTest(kind=kind):
                self.config_path.write_text(json.dumps({kind: "nonfinite"}))
                with self.assertRaisesRegex(ValueError, "nonfinite"):
                    self.prepare()

    def test_optional_names_must_be_safe_unique_and_match_actual_tensor_count(self):
        for key in ("input_names", "output_names"):
            for names in ([], ["one"], ["same", "same"], ["bad/name", "other"], "ab"):
                with self.subTest(key=key, names=names):
                    self.recipe.pop("input_names", None)
                    self.recipe.pop("output_names", None)
                    self.recipe[key] = names
                    with self.assertRaisesRegex(ValueError, "names|count"):
                        self.prepare()

    def test_explicit_recipes_still_require_declared_shapes_by_default(self):
        self.recipe.update(
            input_names=["x", "y"], output_names=["z", "total"], dtype="float32"
        )
        with self.assertRaisesRegex(ValueError, "shape"):
            worker._prepare_model(
                self.recipe,
                self.recipe_path,
                "cpu",
                model_inputs=resolve_inputs(self.recipe, self.recipe_path),
            )


if __name__ == "__main__":
    unittest.main()

"""AOTI export precision boundaries and restoration; compilation is stubbed."""

from pathlib import Path
import sys
import tempfile
import unittest
from unittest import mock

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))

try:
    import torch
except ImportError:
    torch = None


@unittest.skipIf(torch is None, "Torch is required")
class ExportPrecisionTests(unittest.TestCase):
    def exercise_export(self, target, *, fail_at=None, initial_tf32=True):
        from model_builder.export import exporter

        observations = []
        old_precision = torch.get_float32_matmul_precision()
        old_cudnn_tf32 = torch.backends.cudnn.allow_tf32
        self.addCleanup(torch.set_float32_matmul_precision, old_precision)
        self.addCleanup(setattr, torch.backends.cudnn, "allow_tf32", old_cudnn_tf32)
        torch.set_float32_matmul_precision("high")
        torch.backends.cudnn.allow_tf32 = initial_tf32

        def observe(stage):
            observations.append(
                (
                    stage,
                    torch.get_float32_matmul_precision(),
                    torch.backends.cudnn.allow_tf32,
                )
            )
            if stage == fail_at:
                raise RuntimeError("injected " + stage + " failure")

        class Model(torch.nn.Module):
            def forward(self, value):
                observe("eager")
                return value + 1

        def export(*args):
            observe("export")
            return object()

        def compile_package(*args, package_path, **kwargs):
            observe("compile")
            Path(package_path).write_bytes(b"stub package")

        def validate(artifact, inputs, device, directory):
            observe("validate")
            return ((inputs[0] + 1).cpu(),)

        with (
            tempfile.TemporaryDirectory() as temporary,
            mock.patch.object(exporter, "_configure_cuda_export_environment"),
            mock.patch.object(exporter, "_strict_export", side_effect=export),
            mock.patch.object(exporter, "_validate_exported_program", return_value=()),
            mock.patch.object(
                torch._inductor, "aoti_compile_and_package", side_effect=compile_package
            ),
            mock.patch.object(
                exporter, "_run_isolated_aoti_package", side_effect=validate
            ),
        ):
            arguments = dict(
                model_name="precision",
                model_version="1",
                input_names=("input",),
                output_names=("output",),
                target=target,
            )
            if fail_at is None:
                exporter.export_package(
                    Model(), (torch.ones(3),), Path(temporary) / "package", **arguments
                )
            else:
                with self.assertRaisesRegex(RuntimeError, "injected " + fail_at):
                    exporter.export_package(
                        Model(),
                        (torch.ones(3),),
                        Path(temporary) / "package",
                        **arguments,
                    )

        self.assertEqual(torch.get_float32_matmul_precision(), "high")
        self.assertEqual(torch.backends.cudnn.allow_tf32, initial_tf32)
        return observations

    @unittest.skipUnless(
        torch is not None and torch.cuda.is_available(), "CUDA required"
    )
    def test_cuda_export_uses_ieee_fp32_and_restores_caller(self):
        for initial_tf32 in (True, False):
            with self.subTest(initial_tf32=initial_tf32):
                observations = self.exercise_export("cuda", initial_tf32=initial_tf32)
                self.assertEqual(
                    observations,
                    [
                        (stage, "highest", False)
                        for stage in ("eager", "export", "compile", "validate")
                    ],
                )

    @unittest.skipUnless(
        torch is not None and torch.cuda.is_available(), "CUDA required"
    )
    def test_cuda_export_restores_caller_after_each_failure(self):
        stages = ("eager", "export", "compile", "validate")
        for index, stage in enumerate(stages):
            with self.subTest(stage=stage):
                observations = self.exercise_export("cuda", fail_at=stage)
                self.assertEqual(
                    observations,
                    [(observed, "highest", False) for observed in stages[: index + 1]],
                )

    def test_cpu_export_preserves_existing_policy(self):
        self.assertEqual(
            self.exercise_export("cpu"),
            [
                (stage, "high", True)
                for stage in ("eager", "export", "compile", "validate")
            ],
        )


if __name__ == "__main__":
    unittest.main()

"""Shared ONNX graph fixtures; importing test suites does not collect other suites."""

from __future__ import annotations

import numpy as np
import onnx
from onnx import helper, numpy_helper


class _RematerializingNodes:
    def __init__(self, nodes: object) -> None:
        self._nodes = nodes

    def __iter__(self):
        return (
            onnx.NodeProto.FromString(node.SerializeToString()) for node in self._nodes
        )

    def __delitem__(self, index: object) -> None:
        del self._nodes[index]

    def extend(self, nodes: object) -> None:
        self._nodes.extend(nodes)


class _RematerializingGraph:
    def __init__(self, graph: onnx.GraphProto) -> None:
        self._graph = graph

    @property
    def node(self) -> _RematerializingNodes:
        return _RematerializingNodes(self._graph.node)

    def __getattr__(self, name: str) -> object:
        return getattr(self._graph, name)


class _RematerializingModel:
    def __init__(self, model: onnx.ModelProto) -> None:
        self.graph = _RematerializingGraph(model.graph)


def _with_rematerialized_nodes(
    model: onnx.ModelProto,
) -> _RematerializingModel:
    rematerialized = _RematerializingModel(model)
    first = list(rematerialized.graph.node)
    second = list(rematerialized.graph.node)
    assert {id(node) for node in first}.isdisjoint(id(node) for node in second)
    return rematerialized


def _reserve_value_name(model: onnx.ModelProto, name: str, namespace: str) -> None:
    source = model.graph.input[0]

    def value_info() -> onnx.ValueInfoProto:
        value = onnx.ValueInfoProto()
        value.CopyFrom(source)
        value.name = name
        return value

    if namespace == "input":
        model.graph.input.append(value_info())
    elif namespace == "output":
        model.graph.input.append(value_info())
        model.graph.output.append(value_info())
    elif namespace == "value_info":
        model.graph.node.append(helper.make_node("Identity", (source.name,), (name,)))
        model.graph.value_info.append(value_info())
    elif namespace == "initializer":
        model.graph.initializer.append(
            numpy_helper.from_array(np.array(0.0, dtype=np.float32), name=name)
        )
    elif namespace == "node_output":
        model.graph.node.append(helper.make_node("Identity", (source.name,), (name,)))
    else:
        raise AssertionError(f"unsupported namespace: {namespace}")


def _check_model_with_tensorrt_plugins(model: onnx.ModelProto) -> None:
    checkable = onnx.ModelProto.FromString(model.SerializeToString())
    plugin_domain = "pnmir.test"
    for node in checkable.graph.node:
        if node.op_type.startswith("PNMIRExact"):
            node.domain = plugin_domain
    checkable.opset_import.append(helper.make_opsetid(plugin_domain, 1))
    onnx.checker.check_model(checkable, full_check=True)

"""Observable AOTI compiler configuration for profile and option tests."""

from contextlib import contextmanager


class FakeConfig:
    """Observable compiler configuration, not a numerical compiler substitute."""

    def __init__(self):
        self.emulate_divison_rounding = False
        self.fallback_by_default = False
        self.selective_decompose = False
        self.post_grad_custom_pre_pass = None
        self.patch_calls = 0

    @contextmanager
    def patch(self, settings):
        self.patch_calls += 1
        previous = {key: getattr(self, key) for key in settings}
        try:
            for key, value in settings.items():
                setattr(self, key, value)
            yield
        finally:
            for key, value in previous.items():
                setattr(self, key, value)
